def apply_layer_swap_color_by_depth(grid, components):
    """For each component, swap colors from paired layers (depth-paired)"""
    output = [[0]*len(grid[0]) for _ in range(len(grid))]

    for comp_positions in components:
        # Find center
        rs = [p[0] for p in comp_positions]
        cs = [p[1] for p in comp_positions]
        center_r = sum(rs) / len(rs)
        center_c = sum(cs) / len(cs)

        # Sort by distance from center
        import math
        def dist(p):
            dr = p[0] - center_r
            dc = p[1] - center_c
            return dr*dr + dc*dc

        sorted_by_dist = sorted(comp_positions, key=dist)

        # Cluster by distance (unique distances represent layers)
        unique_dists = sorted(set([dist(p) for p in sorted_by_dist]))
        layers = []  # Each layer is list of (position, color)

