            layer = [(p, grid[p[0]][p[1]]) for p in sorted_by_dist if abs(dist(p) - d) < 0.1]
            layers.append((d, layer))  # Store (distance, list_of_pos_color_pairs)

        # Pair layers
        n_layers = len(layers)
        for i in range(n_layers):
            j = n_layers - 1 - i  # Pair with partner from end

            if i == j:
                # Middle layer stays same
                for (p, color) in layers[i][1]:
                    output[p[0]][p[1]] = color
            else:
                # Swap colors between paired layers
