# Final implementation: concentric ring swap
def concentric_swap(grid, components):
    output = [[0]*len(grid[0]) for _ in range(len(grid))]

    for comp in components:
        rs, cs = [p[0] for p in comp], [p[1] for p in comp]
        cr, cc = sum(rs)/len(rs), sum(cs)/len(cs)

        def di(p):
            return abs(p[0]-cr) + abs(p[1]-cc)

        sorted_pos = sorted(comp, key=di)
        n = len(sorted_pos)

        # Map each position to its layer (ring) by grouping same-distance positions
        layers = []
        if sorted_pos:
            cur = [sorted_pos[0]]
            d0 = di(sorted_pos[0])
            for p in sorted_pos[1:]:
                d = di(p)
                if d - d0 > 0.5:
                    layers.append(cur)
                    cur = [p]
                    d0 = d
                else:
                    cur.append(p)
            layers.append(cur)

        # Each position in layer i gets the color from position in layer (n-1-i)
        for layer_idx, layer in enumerate(layers):
            paired_idx = len(layers) - 1 - layer_idx
            paired_layer = layers[paired_idx]
            # Get the paired color (arbitrary position from paired layer)
            if paired_layer:
                paired_color = grid[paired_layer[0][0]][paired_layer[0][1]]
                for p in layer:
                    output[p[0]][p[1]] = paired_color
            else:
                for p in layer:
                    output[p[0]][p[1]] = 0

    return output

